Compose_topCount__Resolved.inputs:
@string(
  min(
    max(
      int(
        coalesce(
          triggerOutputs()?['queries']?['top'],
          outputs('Compose_topCount__Manual'),
          250
        )
      ),
      1
    ),
    500
  )
)

